-- ----------------------------------------------------------------------------
-- Customers: Table: Customers
-- ----------------------------------------------------------------------------
CREATE TABLE customers (
  customer_id                         TEXT                 PRIMARY KEY,
  name                                TEXT                ,
  current_color                       TEXT                ,                     -- The current color assigned to this customer (e.g. red, green, yellow, blue)
  notes                               TEXT                
);
COMMENT ON TABLE customers IS 'Table: Customers';
COMMENT ON COLUMN customers.current_color IS 'The current color assigned to this customer (e.g. red, green, yellow, blue)';

